package cobra //nolint:testpackage

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"gitlab.com/kickr-dev/engine/pkg/files"
)

func TestLicense(t *testing.T) {
	t.Run("error_invalid_config", func(t *testing.T) {
		// Arrange
		destdir := t.TempDir()
		require.NoError(t, os.WriteFile(filepath.Join(destdir, ".kickr.yml"), []byte("version: 1\n"), files.RwRR))

		cmd := licenseCmd(&destdir)
		cmd.SetArgs([]string{})

		// Act
		err := cmd.ExecuteContext(t.Context())

		// Assert
		assert.ErrorContains(t, err, "maintainers")
	})

	t.Run("error_no_license", func(t *testing.T) {
		// Arrange
		destdir := t.TempDir()
		cmd := licenseCmd(&destdir)
		cmd.SetArgs([]string{})

		// Act
		err := cmd.ExecuteContext(t.Context())

		// Assert
		assert.ErrorContains(t, err, "no license given")
	})

	t.Run("error_configured_no_license", func(t *testing.T) {
		// Arrange
		destdir := t.TempDir()
		config := "version: 1\nmaintainers:\n  - name: maintainer\n"
		require.NoError(t, os.WriteFile(filepath.Join(destdir, ".kickr.yml"), []byte(config), files.RwRR))

		cmd := licenseCmd(&destdir)
		cmd.SetArgs([]string{"mit"})

		// Act
		err := cmd.ExecuteContext(t.Context())

		// Assert
		assert.ErrorContains(t, err, "kickr configuration has no 'license' key")
	})

	t.Run("success_configured_license", func(t *testing.T) {
		// Arrange
		destdir := t.TempDir()
		config := "version: 1\nmaintainers:\n  - name: maintainer\nlicense: mit\n"
		require.NoError(t, os.WriteFile(filepath.Join(destdir, ".kickr.yml"), []byte(config), files.RwRR))
		// an existing LICENSE isn't downloaded again without force
		require.NoError(t, os.WriteFile(filepath.Join(destdir, "LICENSE"), []byte("license"), files.RwRR))

		cmd := licenseCmd(&destdir)
		cmd.SetArgs([]string{})

		// Act
		err := cmd.ExecuteContext(t.Context())

		// Assert
		require.NoError(t, err)
		assert.FileExists(t, filepath.Join(destdir, "LICENSE"))
	})

	t.Run("success_no_config", func(t *testing.T) {
		// Arrange
		destdir := t.TempDir()
		require.NoError(t, os.WriteFile(filepath.Join(destdir, "LICENSE"), []byte("license"), files.RwRR))

		cmd := licenseCmd(&destdir)
		cmd.SetArgs([]string{"mit"})

		// Act
		err := cmd.ExecuteContext(t.Context())

		// Assert
		require.NoError(t, err)
	})
}
